import unittest
from app import quote

class QuoteTest(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(quote(3), 100)
    def test_minimum_positive_weight(self):
        self.assertEqual(quote(1), 100)
    def test_boundary(self):
        self.assertEqual(quote(5), 100)
        self.assertEqual(quote(6), 200)
    def test_express(self):
        self.assertEqual(quote(6, True), 250)
    def test_express_adds_fifty_to_lower_weight_rate(self):
        self.assertEqual(quote(1, express=True), 150)
        self.assertEqual(quote(5, express=True), 150)
    def test_explicit_non_express_uses_normal_rate(self):
        self.assertEqual(quote(5, express=False), 100)
        self.assertEqual(quote(6, express=False), 200)
    def test_invalid(self):
        with self.assertRaises(ValueError):
            quote(0)
    def test_negative_weight_is_invalid_even_with_express(self):
        for express in (False, True):
            with self.subTest(express=express):
                with self.assertRaises(ValueError):
                    quote(-1, express=express)
    def test_zero_weight_is_invalid_with_express(self):
        with self.assertRaises(ValueError):
            quote(0, express=True)

